function uptime(s){const d=Math.floor(s/86400),h=Math.floor(s%86400/3600),m=Math.floor(s%3600/60);return d?d+" d "+h+" u":h+" u "+m+" m";}
async function refresh(){try{const d=await api("/api/diagnostics");const mh=d.memoryHealth||{};$("memory-available").textContent=fmt(d.memory.available)+" · "+(mh.availablePct??"—")+"%";meter("memory-available-meter",mh.availablePct||0);$("memory-gtt-used").textContent=fmt(d.gpu.gttUsed)+" / "+fmt(d.gpu.gtt);meter("memory-gtt-meter",mh.gttUsedPct||0);$("memory-swap-used").textContent=fmt(mh.swapUsed)+" / "+fmt(d.memory.swapTotal);meter("memory-swap-meter",mh.swapUsedPct||0);const healthLabel={normal:"Geheugen normaal",warning:"Geheugendruk",critical:"Kritiek geheugentekort"};$("memory-health-state").textContent=healthLabel[mh.level]||"Onbekend";$("memory-health-state").className="runtime-state "+(mh.level==="critical"?"is-missing":mh.level==="warning"?"task-warning":"is-ready");$("memory-health-detail").textContent=(mh.reasons?.length?mh.reasons.join(" · "):"Geen verhoogde geheugendruk gedetecteerd.")+" · Dit zijn momentopnamen; modelramingen blijven schattingen.";$("host-name").textContent=d.host.hostname;$("ram-used").textContent=fmt(d.memory.used);$("ram-detail").textContent=fmt(d.memory.available)+" beschikbaar van "+fmt(d.memory.total);meter("ram-meter",pct(d.memory.used,d.memory.total));$("gtt-total").textContent=fmt(d.gpu.gtt);$("gtt-detail").textContent=fmt(d.gpu.gttUsed)+" in gebruik · "+fmt(d.gpu.vram)+" VRAM";meter("gtt-meter",pct(d.gpu.gttUsed,d.gpu.gtt));$("gpu-busy").textContent=d.gpu.busy==null?"—":d.gpu.busy+"%";$("gpu-detail").textContent=d.gpu.name;meter("gpu-meter",d.gpu.busy||0);$("cpu-count").textContent=d.host.cpuUsage==null?d.host.cpus+" threads":d.host.cpuUsage+"%";meter("cpu-meter",d.host.cpuUsage||0);$("cpu-detail").textContent=d.host.cpuModel+" · "+d.host.cpus+" threads";$("updated-at").textContent=new Date(d.timestamp).toLocaleTimeString("nl-NL");$("last-update").textContent="Bijgewerkt "+new Date(d.timestamp).toLocaleTimeString("nl-NL");state("llama-state",d.runtimes.text==="running"||d.runtimes.text==="starting",true);state("sd-state",d.runtimes.image==="running"||d.runtimes.image==="starting",true);
$("diag-cpu-model").textContent=d.host.cpuModel;$("diag-cpu-count").textContent=d.host.cpus;$("diag-cpu-usage").textContent=d.host.cpuUsage==null?"—":d.host.cpuUsage+"%";$("diag-kernel").textContent=d.host.release;$("diag-uptime").textContent=uptime(d.host.uptime);$("diag-ram-total").textContent=fmt(d.memory.total);$("diag-ram-used").textContent=fmt(d.memory.used);$("diag-ram-free").textContent=fmt(d.memory.available);$("diag-swap").textContent=fmt(d.memory.swapFree);$("diag-gpu").textContent=d.gpu.name;$("diag-vram").textContent=fmt(d.gpu.vram);$("diag-gtt").textContent=fmt(d.gpu.gtt);$("diag-gtt-used").textContent=fmt(d.gpu.gttUsed);$("diag-gpu-busy").textContent=d.gpu.busy==null?"—":d.gpu.busy+"%";$("diag-ttm").textContent=d.gpu.ttm==null?"—":Number(d.gpu.ttm).toLocaleString("nl-NL")+" pages";$("diag-updated").textContent="Bijgewerkt "+new Date(d.timestamp).toLocaleTimeString("nl-NL");$("temperature-list").innerHTML=(d.temperatures||[]).map(x=>'<article class="model-card"><b>'+esc(x.name)+'</b><p>'+Number(x.temperature).toFixed(1)+' °C</p></article>').join("")||'<div class="empty-state">Geen temperatuursensoren beschikbaar via hwmon.</div>';$("disk-list").innerHTML=(d.disks||[]).map(x=>'<article class="model-card"><b>'+esc(x.path)+'</b><p>'+fmt(x.free)+' vrij van '+fmt(x.total)+'</p><div class="meter"><i style="width:'+pct(x.used,x.total)+'%"></i></div></article>').join("");}catch(e){$("last-update").textContent="Verbinding mislukt";console.error(e);}}
