function updateImageEditorLock(i){const ready=!!(i?.model&&i.state==="running"),fields=$("image-editor-fields"),hint=$("image-editor-lock");if(fields)fields.disabled=!ready;if(hint){hint.hidden=ready;hint.textContent=i?.state==="starting"?"Beeldmodel wordt geladen…":"Laad eerst een beeldmodel om afbeeldingen te maken of te bewerken.";}const generate=$("generate-image");if(generate&&!imageBusy)generate.disabled=!ready;}
async function loadRuntime(){try{const r=await api("/api/runtime");const t=r.text,i=r.image;activeImageRuntime=i;updateImageEditorLock(i);const chatModelSelect=$("chat-model");if(t.model&&[...chatModelSelect.options].some(o=>o.value===t.model))chatModelSelect.value=t.model;else if(!t.model)chatModelSelect.value="";const quickModel=$("chat-load-model-select");if(quickModel&&t.model&&[...quickModel.options].some(o=>o.value===t.model)){quickModel.value=t.model;$("chat-load-summary").textContent="Actief · "+t.model.split("/").pop();}else if(quickModel&&!t.model)$("chat-load-summary").textContent="Model laden";const context=t.context||Number($("load-context").value)||4096;$("chat-context-size").textContent=(t.context?"Context ":"Context bij laden ")+Number(context).toLocaleString("nl-NL")+" tokens";const status={stopped:"Gestopt",starting:"Starten…",running:"Actief",stopping:"Stoppen…",error:"Fout"};$("text-active-model").textContent=t.model?t.model.split("/").pop():"Geen GGUF-model geladen";$("text-active-detail").textContent=t.error?"Fout: "+t.error.split("\n").slice(-3).join(" · ").slice(-260):t.mmproj?"Vision-projector: "+t.mmproj.split("/").pop():"llama.cpp · "+(status[t.state]||t.state);$("text-active-detail").title=t.error||"";$("text-active-state").textContent=status[t.state]||t.state;$("unload-text").disabled=!t.model;$("image-active-model").textContent=i.model?i.model.split("/").pop():"Geen beeldmodel geladen";$("image-active-detail").textContent=i.error?"Fout: "+i.error.split("\n").slice(-3).join(" · ").slice(-260):"stable-diffusion.cpp · "+(status[i.state]||i.state);$("image-active-detail").title=i.error||"";$("image-active-state").textContent=status[i.state]||i.state;$("unload-image").disabled=!i.model;if(imageCatalog?.checkpoints)renderImageAssetInventory();}catch(e){console.warn(e);}}
function renderLocal(){const root=$("local-models");const count=$("text-library-count");if(!localModels.length){root.innerHTML='<div class="empty-state">Geen lokale GGUF-bestanden gevonden. Download modellen via de Modelwinkel.</div>';if(count)count.textContent="0 tekstmodellen";return;}const activeName=$("text-active-model")?.textContent||"";root.innerHTML='<div class="asset-group"><div class="asset-group-title"><b>GGUF · llama.cpp</b><span>'+localModels.length+' modellen</span></div>'+localModels.map((m,i)=>{const active=activeName===m.name;return '<div class="asset-row text-model-row" data-search="'+esc((m.name+' '+m.path+' '+(m.meta?.architecture||'')).toLowerCase())+'"><div class="asset-file text-model-file"><strong>'+esc(m.name)+'</strong><small>'+fmtBytes(m.size)+' · '+esc(m.meta?.architecture||"GGUF")+(m.meta?.layers?" · "+m.meta.layers+" lagen":"")+(m.meta?.parameters?" · "+Number(m.meta.parameters).toLocaleString("nl-NL")+" parameters":"")+(m.meta?.context?" · max ctx "+Number(m.meta.context).toLocaleString("nl-NL"):"")+'</small><small class="text-model-plan">'+(active?'Actief geladen · ':'')+(m.plan.fit==="likely"?"Past waarschijnlijk":m.plan.fit==="tight"?"CPU/GPU-mix":"Waarschijnlijk te groot")+' · Context '+$("load-context").value+' · totaal '+fmt(m.plan.required)+' · KV-cache '+fmt(m.plan.kvBytes)+'</small>'+(m.mmprojCandidates?.length?'<label class="mmproj-row">Visionprojector<select data-mmproj="'+i+'"><option value="">Automatisch</option><option value="none">Geen mmproj</option>'+m.mmprojCandidates.map(x=>'<option value="'+esc(x.path)+'">'+esc(x.name)+'</option>').join("")+'</select></label>':'')+'</div><div class="asset-actions"><button class="text-button" data-delete-local="'+i+'">Verwijderen</button><button class="primary-button" data-load-local="'+i+'" '+(active?'disabled':'')+'>Laden</button></div></div>';}).join("")+'</div>';const q=$("text-model-search").value.trim().toLowerCase();if(q)root.querySelectorAll(".text-model-row").forEach(row=>row.hidden=!row.dataset.search.includes(q));if(count)count.textContent=(q?root.querySelectorAll('.text-model-row:not([hidden])').length+" van ":"")+localModels.length+" tekstmodellen";root.querySelectorAll("[data-load-local]").forEach(b=>b.addEventListener("click",()=>{const i=Number(b.dataset.loadLocal),sel=root.querySelector('[data-mmproj="'+i+'"]');loadTextModel(localModels[i],sel?sel.value:undefined);}));root.querySelectorAll("[data-delete-local]").forEach(b=>b.addEventListener("click",async()=>{const m=localModels[Number(b.dataset.deleteLocal)];if(!confirm("Verwijder "+m.name+" definitief van de schijf?"))return;try{await post("/api/models/delete",{path:m.path});toast("Model verwijderd");loadModels();}catch(e){toast(e.message);}}));}
async function loadModels(){try{const d=await api("/api/models?context="+encodeURIComponent($("load-context").value||4096)+"&cacheK="+encodeURIComponent($("load-k").value||"q8_0"));localModels=d.local||[];renderLocal();const s=$("chat-model"),old=s.value;s.innerHTML='<option value="">Selecteer model</option>';localModels.forEach(m=>{const o=document.createElement("option");o.value=m.path;o.textContent=m.name;s.append(o);});if([...s.options].some(o=>o.value===old))s.value=old;const quick=$("chat-load-model-select"),quickOld=quick.value;quick.innerHTML='<option value="">Selecteer lokaal GGUF-model</option>';localModels.forEach(m=>{const o=document.createElement("option");o.value=m.path;o.textContent=m.name+" · "+fmtBytes(m.size);quick.append(o);});if([...quick.options].some(o=>o.value===quickOld))quick.value=quickOld;await loadRuntime();}catch(e){$("local-models").innerHTML='<div class="empty-state">Modelbibliotheek: '+esc(e.message)+'</div>';}}
