$("chat-load-model-select").addEventListener("change",()=>{const m=localModels.find(x=>x.path===$("chat-load-model-select").value);const wrap=$("chat-mmproj-wrap"),sel=$("chat-load-mmproj");wrap.hidden=!(m?.mmprojCandidates?.length);sel.innerHTML='<option value="">Automatisch</option><option value="none">Geen mmproj</option>'+(m?.mmprojCandidates||[]).map(x=>'<option value="'+esc(x.path)+'">'+esc(x.name)+'</option>').join("");});
