async function marketSearch(e){if(e)e.preventDefault();const q=$("market-query").value.trim(),type=$("market-type").value,category=$("market-image-category").value,source=$("market-source").value,repos=$("market-repositories"),files=$("market-file-list");repos.innerHTML='<div class="empty-state">Zoeken…</div>';files.innerHTML='<div class="empty-state">Selecteer een repository.</div>';$("market-files-title").textContent="Modelbestanden";$("market-files-subtitle").textContent=type==="text"?"Selecteer een GGUF-repository":"Selecteer een beeldmodelrepository";try{if(source==="civitai"||source==="civitai-red"){if(type==="text"){repos.innerHTML='<div class="empty-state">Civitai is bedoeld voor beeldmodellen en assets. Kies Beeldmodellen.</div>';return;}const d=await api("/api/market/civitai/search?q="+encodeURIComponent(q)+"&category="+encodeURIComponent(category)+"&source="+encodeURIComponent(source));civitaiModels=d.models||[];repos.innerHTML=civitaiModels.map((m,i)=>'<button class="market-repo" data-civ-model="'+i+'">'+(m.versions?.[0]?.images?.[0]?.url?'<img class="civ-preview" loading="lazy" src="'+esc(m.versions[0].images[0].url.replace('/original=true/','/width=450/'))+'" alt="Voorbeeld van '+esc(m.name)+'" onerror="this.hidden=true">':'')+'<b>'+esc(m.name)+'</b><small>'+esc(m.type)+' · '+esc(m.creator)+' · '+Number(m.downloads).toLocaleString("nl-NL")+' downloads'+(m.nsfw?' · 18+':'')+'</small></button>').join('')||'<div class="empty-state">Geen Civitai-modellen gevonden.</div>';repos.querySelectorAll('[data-civ-model]').forEach(b=>b.addEventListener('click',()=>openCivitaiModel(Number(b.dataset.civModel),b)));$("market-files-title").textContent="Modelversies en bestanden";$("market-files-subtitle").textContent="Selecteer een model";files.innerHTML='<div class="empty-state">Selecteer links een model om versies en bestanden te bekijken.</div>';return;}const d=type==="text"?await api("/api/market/search?q="+encodeURIComponent(q)):await api("/api/market/image-search?q="+encodeURIComponent(q)+"&category="+encodeURIComponent(category));const items=d.repositories||[];repos.innerHTML=items.map((x,i)=>'<button class="market-repo" data-repo-index="'+i+'"><b>'+esc(x.id)+'</b><small>'+Number(x.downloads).toLocaleString("nl-NL")+' downloads · '+(type==="image"?esc(x.pipeline||category)+" · "+Number(x.likes).toLocaleString("nl-NL")+" likes":Number(x.likes).toLocaleString("nl-NL")+" likes")+'</small></button>').join("")||'<div class="empty-state">Geen repositories gevonden.</div>';repos.querySelectorAll('[data-repo-index]').forEach((b,i)=>b.addEventListener('click',()=>type==="text"?openRepo(items[i].id,b):openImageRepo(items[i].id,category,b)));}catch(err){repos.innerHTML='<div class="empty-state">'+esc(err.message)+'</div>';}}
