async function loadQueue(){
 try{
  const d=await api("/api/market/queue"),q=d.queue||[];let completedText=false,completedImage=false,completedVideo=false;
  for(const x of q){if(queueInitialized&&x.status==="done"&&queueSeen[x.id]!=="done"){if(x.category==="text")completedText=true;else if(String(x.category).startsWith("video_"))completedVideo=true;else completedImage=true;}queueSeen[x.id]=x.status;}queueInitialized=true;
  const queueHtml=q.map(x=>{
   const statusLabel=({queued:"In wachtrij",downloading:"Downloaden",paused:"Gepauzeerd",error:"Fout",done:"Voltooid",missing:"Bestand ontbreekt",cancelled:"Geannuleerd"})[x.status]||x.status;
   const progress=x.size?pct(x.downloaded,x.size):0,ext=String(x.file||"").toLowerCase().split(".").pop(),canResume=["paused","error","missing"].includes(x.status)&&(x.category==="text"?ext==="gguf":["safetensors","ckpt","gguf","sft","bin","onnx"].includes(ext));
   return '<div class="queue-item"><div class="queue-top"><b>'+esc(x.name)+'</b><span class="queue-status '+esc(x.status)+'">'+esc(statusLabel)+'</span></div><div class="meter"><i style="width:'+progress+'%"></i></div><small>'+fmtBytes(x.downloaded||0)+' / '+(x.size?fmtBytes(x.size):"onbekende grootte")+' · '+(x.speed?fmtBytes(x.speed)+"/s":"")+(x.error?" · "+esc(x.error):"")+'</small><div class="queue-actions">'+(x.status==="downloading"?'<button data-queue="pause" data-id="'+x.id+'">Pauze</button>':"")+(canResume?'<button data-queue="resume" data-id="'+x.id+'">Hervatten</button>':"")+'<button data-queue="remove" data-id="'+x.id+'" title="'+(x.status==="done"?"Verwijdert alleen deze geschiedenisregel; modelbestand blijft staan":"Verwijdert dit wachtrij-item en eventuele gedeeltelijke download")+'">'+(x.status==="done"?"Uit geschiedenis verwijderen":"Uit wachtrij verwijderen")+'</button></div></div>';
  }).join("")||'<div class="empty-state">Geen downloads in de wachtrij.</div>';
  const root=$("download-queue");if(root){root.innerHTML=queueHtml;root.querySelectorAll("[data-queue]").forEach(b=>b.addEventListener("click",async()=>{b.disabled=true;try{await post("/api/market/action",{id:b.dataset.id,action:b.dataset.queue});await loadQueue();}catch(e){toast(e.message);b.disabled=false;}}));}
  if(completedText)await loadModels();if(completedImage)await loadImageModels();if(completedVideo){await loadNativeVideoModels();await loadNativeVideoEngine();}if(completedText||completedImage||completedVideo)toast("Download voltooid · modelbibliotheek bijgewerkt");
 }catch(e){console.warn(e);}
}
function civitaiBaseFamily(value){
 const text=String(value||"").toLowerCase();
 if(text.includes("flux"))return "flux";
 if(/sdxl|stable diffusion xl|pony|illustrious|animagine/.test(text))return "sdxl";
 if(/sd.?1[._ ]?5|stable diffusion 1.5/.test(text))return "sd15";
 if(/sd.?2/.test(text))return "sd2";
 if(/sd.?3/.test(text))return "sd3";
 if(text.includes("kolors"))return "kolors";
 return "";
}
function renderCivitaiVersions(model,root,filters){
 const runtimeModel=activeImageRuntime?.model||$("image-model")?.value||$("image-page-model")?.value||"";
 const runtimeFamily=civitaiBaseFamily(runtimeModel.split(/[\\/]/).pop());
 const supported=(model.versions||[]).map(version=>{
  const files=(version.files||[]).filter(file=>["safetensors","gguf","onnx","bin","pt","pth","ckpt","sft"].includes(String(file.name).toLowerCase().split(".").pop()));
  const largest=Math.max(0,...files.map(file=>Number(file.size)||0));
  const family=civitaiBaseFamily(version.baseModel);
  return {...version,files,largest,family,compatible:!runtimeFamily||!family?null:family===runtimeFamily};
 }).filter(version=>version.files.length);
 const query=filters.query.trim().toLowerCase(),maxSize=Number(filters.maxSize)||0;
 let versions=supported.map(version=>({...version,files:version.files.filter(file=>{
  const haystack=[version.name,version.baseModel,file.name,file.format,file.type,(version.trainedWords||[]).join(" ")].join(" ").toLowerCase();
  return (!query||haystack.includes(query))&&(!maxSize||(Number(file.size)||0)<=maxSize);
 })})).filter(version=>version.files.length);
 versions.sort((a,b)=>filters.sort==="smallest"?a.largest-b.largest:filters.sort==="largest"?b.largest-a.largest:filters.sort==="compatible"?((b.compatible===true)-(a.compatible===true))||new Date(b.createdAt||0)-new Date(a.createdAt||0):new Date(b.createdAt||0)-new Date(a.createdAt||0));
 const totalFiles=versions.reduce((sum,version)=>sum+version.files.length,0);
 const prettyDate=value=>{if(!value)return "Datum onbekend";const date=new Date(value);return Number.isNaN(date.getTime())?"Datum onbekend":date.toLocaleDateString("nl-NL",{year:"numeric",month:"short",day:"numeric"});};
 const sizeOptions=[["0","Alle groottes"],["104857600","Tot 100 MB"],["524288000","Tot 500 MB"],["1073741824","Tot 1 GB"],["2147483648","Tot 2 GB"]];
 root.innerHTML='<div class="civ-version-toolbar"><label class="civ-version-search"><span>Zoek versie of bestand</span><input id="civ-version-query" type="search" placeholder="Bijv. V3, SDXL, fp16, bestandsnaam…" value="'+esc(filters.query)+'"></label><label><span>Maximale grootte</span><select id="civ-version-size">'+sizeOptions.map(([value,label])=>'<option value="'+value+'" '+(String(filters.maxSize)===value?'selected':'')+'>'+label+'</option>').join("")+'</select></label><label><span>Sorteren</span><select id="civ-version-sort"><option value="newest" '+(filters.sort==="newest"?'selected':'')+'>Nieuwste versie</option><option value="smallest" '+(filters.sort==="smallest"?'selected':'')+'>Kleinste bestanden</option><option value="largest" '+(filters.sort==="largest"?'selected':'')+'>Grootste bestanden</option><option value="compatible" '+(filters.sort==="compatible"?'selected':'')+' '+(!runtimeFamily?'disabled':'')+'>Passend bij actief model</option></select></label><div class="civ-version-expand"><button type="button" class="secondary-button" data-civ-expand="all">Alles uitklappen</button><button type="button" class="text-button" data-civ-expand="none">Alles inklappen</button></div></div><div class="civ-version-summary"><b>'+versions.length+' van '+supported.length+' versies</b><span>'+totalFiles+' bestanden · '+(query||maxSize?"filters actief":"nieuwste versies eerst")+'</span></div>'+versions.map((version,index)=>{
  const files=version.files.slice().sort((a,b)=>(Number(b.primary)-Number(a.primary))||(Number(b.size)||0)-(Number(a.size)||0));
  const label=version.name||"Naamloze versie";
  const primary=files.find(file=>file.primary)||files[0];
  const versionSize=fmtBytes(version.largest);
  const fitBadge=version.compatible===true?'<span class="civ-fit-badge is-match">Past bij actief model</span>':version.compatible===false?'<span class="civ-fit-badge is-mismatch">Ander basismodel</span>':'<span class="civ-fit-badge">'+(runtimeFamily?'Niet vast te stellen':'Kies/laad een checkpoint')+'</span>';
  return '<details class="civ-version-card '+(version.compatible===true?'is-compatible':'')+'" '+(index===0?'open':'')+'><summary><span class="civ-version-title"><b>'+esc(label)+'</b><small>'+esc(version.baseModel||"Basismodel onbekend")+' · '+prettyDate(version.createdAt)+'</small></span><span class="civ-version-meta">'+fitBadge+'<b>'+versionSize+'</b><small>'+files.length+' bestand'+(files.length===1?'':'en')+'</small></span><span class="civ-version-chevron">⌄</span></summary><div class="civ-version-files">'+files.map(file=>{
   const scan=String(file.scan||"Unknown"),scanClass=/success/i.test(scan)?"is-safe":/danger|error/i.test(scan)?"is-warning":"";
   return '<div class="civ-version-file"><div class="civ-version-file-main"><b title="'+esc(file.name)+'">'+esc(file.name)+'</b><div class="civ-version-file-meta"><span>'+fmtBytes(file.size)+'</span><span>'+esc(file.format||String(file.name).split(".").pop().toUpperCase())+'</span><span class="'+scanClass+'">'+esc(scan)+'</span>'+(file.primary?'<span class="civ-primary-label">Primair</span>':'')+'</div></div><button class="primary-button" type="button" data-civ-download="'+esc(String(version.id))+'" data-civ-file="'+esc(file.name)+'" data-civ-file-id="'+esc(String(file.id||""))+'">Download</button></div>';
  }).join("")+(version.trainedWords?.length?'<div class="civ-trigger-words"><span>Trigger words</span>'+esc(version.trainedWords.join(", "))+'</div>':'')+'</div></details>';
 }).join("")||'<div class="empty-state">Geen bestanden gevonden met deze filters. Pas de zoekterm of maximale bestandsgrootte aan.</div>';
 const queryInput=root.querySelector("#civ-version-query");
 queryInput.addEventListener("input",()=>{filters.query=queryInput.value;const pos=queryInput.selectionStart;renderCivitaiVersions(model,root,filters);const next=root.querySelector("#civ-version-query");next.focus();next.setSelectionRange(pos,pos);});
 root.querySelector("#civ-version-size").addEventListener("change",event=>{filters.maxSize=event.target.value;renderCivitaiVersions(model,root,filters);});
 root.querySelector("#civ-version-sort").addEventListener("change",event=>{filters.sort=event.target.value;renderCivitaiVersions(model,root,filters);});
 root.querySelectorAll("[data-civ-expand]").forEach(button=>button.addEventListener("click",()=>root.querySelectorAll(".civ-version-card").forEach(card=>card.open=button.dataset.civExpand==="all")));
 root.querySelectorAll("[data-civ-download]").forEach(button=>button.addEventListener("click",async()=>{
  const version=model.versions.find(item=>String(item.id)===button.dataset.civDownload),file=version?.files?.find(item=>item.name===button.dataset.civFile);if(!version||!file)return;
  button.disabled=true;try{await post("/api/market/civitai/download",{versionId:version.id,fileName:file.name,size:file.size,category:$("market-image-category").value,fileType:file.type,format:file.format,fileId:file.id,source:$("market-source").value});toast("Civitai-model toegevoegd aan downloadwachtrij");loadQueue();}catch(error){toast(error.message);button.disabled=false;}
 }));
}
