let conditioningAutoLoadBusy=false,conditioningAutoLoadTimer=null;
async function autoLoadConditioning(){
 if(conditioningAutoLoadBusy)return;
 const adapter=$("image-ipadapter").value,vision=$("image-clipvision").value;
 if(!adapter&&!vision)return;
 if(!adapter||!vision){toast(!adapter?"Selecteer ook een IP-Adapter-model":"Selecteer ook een CLIP Vision-encoder");return;}
 const model=activeImageRuntime?.model||$("image-page-model").value||$("image-model").value;
 if(!model){toast("Selecteer eerst een beeldcheckpoint; IP-Adapter en CLIP Vision worden daarna automatisch geladen.");return;}
 conditioningAutoLoadBusy=true;
 const adapterSelect=$("image-ipadapter"),visionSelect=$("image-clipvision");
 adapterSelect.disabled=true;visionSelect.disabled=true;
 try{toast("IP-Adapter en CLIP Vision automatisch laden…");await loadImageCheckpoint(model);}
 finally{conditioningAutoLoadBusy=false;adapterSelect.disabled=false;visionSelect.disabled=false;}
}
