$("video-source").addEventListener("change",async e=>{const f=e.target.files?.[0];videoSourceData=null;videoSourceFile=null;$("video-source-preview-wrap").hidden=true;if(!f)return;if(!/^image\/(png|jpeg|webp)$/.test(f.type)||f.size>16*1024*1024){toast("Kies een PNG-, JPEG- of WebP-afbeelding van maximaal 16 MB");e.target.value="";return;}try{videoSourceData=await readData(f);videoSourceFile=f;$("video-source-preview").src=videoSourceData;$("video-source-name").textContent=f.name+" · "+fmtBytes(f.size);$("video-source-preview-wrap").hidden=false;}catch(err){toast(err.message);}});
$("video-source-remove").addEventListener("click",()=>{videoSourceData=null;videoSourceFile=null;$("video-source").value="";$("video-source-preview-wrap").hidden=true;});
function showVideoResult(job){if(job.state==="completed"&&job.videos?.length){$("video-result").innerHTML=job.videos.map(v=>'<video class="video-player" controls autoplay muted playsinline src="'+esc(v.url)+'"></video><a class="primary-button video-download" href="'+esc(v.url)+'" download="'+esc(v.name)+'">Video downloaden</a>').join("");$("video-progress").value=100;$("video-status").textContent="Video voltooid en opgeslagen in je videobibliotheek.";}else if(job.state==="error"){$("video-status").textContent="Generatie mislukt: "+(job.error||"Onbekende fout");$("video-progress").hidden=true;}else if(job.state==="cancelled"){$("video-status").textContent="Video-generatie gestopt.";$("video-progress").hidden=true;}else{$("video-status").textContent=job.state==="running"?"Video wordt gegenereerd door "+(job.engine==="native"?"stable-diffusion.cpp · Vulkan · segment "+(job.progress?.segment||job.segment||1)+"/"+(job.progress?.totalSegments||job.segmentCount||1):"ComfyUI")+"…":"Video staat in de "+(job.engine==="native"?"native GPU":"ComfyUI")+"-wachtrij…";$("video-progress").hidden=false;}}
async function prepareNativeVideoImage(data,width,height){return await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const canvas=document.createElement("canvas");canvas.width=width;canvas.height=height;const ctx=canvas.getContext("2d");const scale=Math.max(width/img.width,height/img.height),w=img.width*scale,h=img.height*scale;ctx.drawImage(img,(width-w)/2,(height-h)/2,w,h);resolve(canvas.toDataURL("image/jpeg",.92));};img.onerror=()=>reject(Error("Startafbeelding kon niet worden voorbereid"));img.src=data;});}
async function pollVideoJob(){if(!videoJobId)return;try{const d=await api("/api/video/jobs/"+encodeURIComponent(videoJobId)),job=d.job;showVideoResult(job);if(job.progress?.total_steps){$("video-progress").value=Math.round(100*(job.progress.step||0)/job.progress.total_steps);}if(["completed","error","cancelled"].includes(job.state)){clearInterval(videoPollTimer);videoPollTimer=null;videoJobId=null;$("video-generate").disabled=( $("video-backend").value==="native"?!nativeVideoRuntimeReady:!videoWorkflow||!videoEngineReady);$("video-cancel").hidden=true;if(job.state==="completed")await loadVideoLibrary();return;}}catch(e){$("video-status").textContent="Status ophalen mislukt: "+e.message;}}
$("video-generate").addEventListener("click",async()=>{const native=($("video-backend").value||"native")==="native";if(native&&!nativeVideoRuntimeReady)return toast("Laad eerst een videomodel in de native Vulkan-engine");if(!native&&!videoWorkflow)return toast("Importeer eerst een ComfyUI API-workflow");if(!native&&!videoEngineReady)return toast("ComfyUI is niet bereikbaar");if(videoMode==="image"&&!videoSourceData)return toast("Kies eerst een startafbeelding");const prompt=$("video-prompt").value.trim();if(!prompt)return toast("Vul eerst een videoprompt in");const [w,h]=($("video-resolution").value||"512x288").split("x").map(Number),fps=Number($("video-fps").value)||12;const duration=Math.max(1,Math.min(60,Number($("video-duration").value)||4));let frames=Math.max(9,Math.min(289,Math.round(duration*fps)));if(native)frames=Math.max(5,Math.min(81,Math.round((frames-1)/4)*4+1));$("video-generate").disabled=true;$("video-cancel").hidden=false;$("video-progress").hidden=false;$("video-progress").removeAttribute("value");$("video-status").textContent=native?"Native Vulkan-videogeneratie voorbereiden…":"ComfyUI-workflow voorbereiden…";$("video-result").innerHTML='<div class="empty-state">Video wordt voorbereid…</div>';try{const payload={mode:videoMode,duration,prompt,negative:$("video-negative").value,image:native&&videoMode==="image"?await prepareNativeVideoImage(videoSourceData,w,h):videoSourceData,width:w,height:h,fps,frames,steps:Number($("video-steps").value)||8,cfg:Number($("video-cfg").value)||6,flowShift:Number($("video-flow-shift").value)||3,seed:Number($("video-seed").value)};const d=native?await post("/api/video/native/generate",payload):await post("/api/video/generate",{...payload,workflow:videoWorkflow});videoJobId=d.job.id;await pollVideoJob();if(videoJobId)videoPollTimer=setInterval(pollVideoJob,2500);}catch(e){$("video-status").textContent="Starten mislukt: "+e.message;$("video-progress").hidden=true;$("video-cancel").hidden=true;$("video-generate").disabled=native?!nativeVideoRuntimeReady:!videoWorkflow||!videoEngineReady;toast(e.message);}});
$("video-cancel").addEventListener("click",async()=>{try{await post("/api/video/cancel",{});if(videoPollTimer)clearInterval(videoPollTimer);videoPollTimer=null;videoJobId=null;$("video-cancel").hidden=true;$("video-generate").disabled=( $("video-backend").value==="native"?!nativeVideoRuntimeReady:!videoWorkflow||!videoEngineReady);$("video-status").textContent="Stopverzoek verzonden naar "+($("video-backend").value==="native"?"de native GPU-engine":"ComfyUI")+".";$("video-progress").hidden=true;}catch(e){toast(e.message);}});
$("video-refresh").addEventListener("click",()=>{loadVideoStatus();loadVideoLibrary();});
updateVideoMode();
$("video-model-file").addEventListener("change",e=>{const f=e.target.files?.[0];$("video-model-upload-status").textContent=f?f.name+" · "+fmtBytes(f.size):"Nog geen modelbestand gekozen.";});
$("video-model-file").addEventListener("change",async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>40*1024**3){toast("Modelbestand is groter dan 40 GiB");return;}const progress=$("video-model-upload-progress");progress.hidden=false;progress.value=0;$("video-model-upload-status").textContent="Uploaden…";try{const folder=$("video-model-folder").value;const result=await new Promise((resolve,reject)=>{const x=new XMLHttpRequest();x.open("POST","/api/video/models/upload?folder="+encodeURIComponent(folder));x.setRequestHeader("X-File-Name",encodeURIComponent(f.name));x.upload.onprogress=e=>{if(e.lengthComputable)progress.value=Math.round(e.loaded/e.total*100);};x.onload=()=>{let d={};try{d=JSON.parse(x.responseText);}catch{}if(x.status>=200&&x.status<300)resolve(d);else reject(Error(d.error||"Upload HTTP "+x.status));};x.onerror=()=>reject(Error("Uploadverbinding verbroken"));x.send(f);});$("video-model-upload-status").textContent="Geïnstalleerd: "+result.name+" · "+fmtBytes(result.size)+" · "+result.folder;toast("Videomodel geïnstalleerd");await loadVideoStatus();}catch(err){$("video-model-upload-status").textContent="Upload mislukt: "+err.message;toast(err.message);}finally{progress.hidden=true;e.target.value="";}});
